{
  "hypotheses": [
    {
      "table": "fda_snapshot.recalls",
      "column": "openfda_product_ndc",
      "transform": "segments_to_11",
      "rationale": "The hospital stores 11-digit NDCs. The recalls table has an openfda_product_ndc column, but its samples are null. However, the code_info column contains NDC-like strings with dates and counts, and openfda_package_ndc exists. The product_ndc format in related tables (fda_snapshot.ndc_packages) shows 5-4-2 hyphenated segments that need padding to 11 digits."
    },
    {
      "table": "fda_snapshot.shortages",
      "column": "package_ndc",
      "transform": "segments_to_11",
      "rationale": "The shortages table has package_ndc column with samples like '0009-0225-02', '0009-0331-02', '0009-0395-14'. These are clearly 5-4-2 hyphenated NDC format. The transform segments_to_11 will pad each segment to the standard lengths (5, 4, 2) totaling 11 digits, matching the hospital's hospital.item_master.ndc11 format."
    },
    {
      "table": "fda_snapshot.ndc_packages",
      "column": "product_ndc",
      "transform": "segments_to_11",
      "rationale": "The ndc_packages table has product_ndc column with samples '82953-020', '45802-042', '45802-042'. These are 5-4 and 5-2 segment NDCs missing trailing segments. The segments_to_11 transform will pad each segment to standard lengths (5-4-2) producing 11-digit NDCs matching the hospital's hospital.item_master.ndc11 format."
    },
    {
      "table": "wholesaler.catalog",
      "column": "ndc",
      "transform": "segments_to_11",
      "rationale": "The wholesaler.catalog has ndc column with samples '143926901', '25021070102', '31722030725'. These appear to be 11-digit NDCs already without hyphens, but some may be missing leading zeros. The segments_to_11 transform ensures consistent 11-digit format by padding segments appropriately, though identity might also work if already correct length."
    }
  ]
}

{
  "items": [
